GUIDES: dict[str, Guide] = {g.id: g for g in _GUIDES}

# Analizdeki kontrol → rehber eşlemesi ("<alan>.<anahtar>"; alan: web | gbp | social)
CHECK_TO_GUIDE: dict[str, str] = {}
for _guide in _GUIDES:
    for _key in _guide.check_keys:
        CHECK_TO_GUIDE[_key] = _guide.id

# Rehberi gerektirmeyen (satış sorunu olmayan) kontroller
NO_GUIDE_CHECKS = {"gbp.business_status"}

# Hizmet → ilgili rehber (fırsat kartlarındaki "Nasıl çözülür?" için, kanıtlı sorun bulunmayan olası ihtiyaçlarda)
SERVICE_TO_GUIDE = {
    "Google Ads": "reklam_google_ads", "Yerel SEO": "reklam_yerel", "Sosyal Medya Reklamları": "reklam_marka", "Matbaa": "matbaa_kartvizit",
    "Tabela": "matbaa_tabela", "Branda Baskı": "matbaa_branda", "Promosyon Ürünleri": "matbaa_promosyon", "Davetiye": "matbaa_davetiye",
    "Araç Giydirme": "arac_giydirme", "Fotoğraf ve Video İçerik": "foto_video", "Kurumsal Kimlik": "kurumsal_kimlik", "Grafik Tasarım": "kurumsal_kimlik",
    "Sosyal Medya Yönetimi": "sosyal_yok", "Kurumsal Web Sitesi": "web_yok", "E-Ticaret": "web_eticaret",
}


def guide_for_check(area: str, key: str) -> Guide | None:
    area = "web" if area == "website" else area  # analizde alan adı "website"; rehber eşlemesinde "web"
    guide_id = CHECK_TO_GUIDE.get(f"{area}.{key}")
    return GUIDES.get(guide_id) if guide_id else None


def render_guide(guide: Guide, *, business: str | None = None, place: str | None = None, sector: str | None = None, phrase: str | None = None) -> dict:
    """Yer tutucuları doldurur. İşletme bilgisi yoksa genel ifadeler kullanılır (uydurma isim/şehir yazılmaz)."""
    values = {
        "isletme": business or "işletmeniz",
        "sehir": place or "bölgenizde",
        "sektor": sector or "sektörünüzde",
        "kelime": phrase or (sector.lower() if sector else "hizmet"),
    }

    def fill(text: str) -> str:
        for key, value in values.items():
            text = text.replace("{" + key + "}", value)
        return text

    return {
        "id": guide.id, "category": guide.category, "title": guide.title, "services": list(guide.services), "check_keys": list(guide.check_keys),
        "sections": {
            "what": fill(guide.what), "why": fill(guide.why), "solution": fill(guide.solution), "steps": [fill(s) for s in guide.steps],
            "pitch": fill(guide.pitch), "offer": fill(guide.offer), "questions": [fill(q) for q in guide.questions], "verify": [fill(v) for v in guide.verify],
        },
    }
